    /**
     * El trazo de un icono, o cadena vacía si no existe.
     *
     * Vacío y no una excepción: un icono que falta deja un hueco, y eso no justifica tumbar la
     * pantalla que lo pedía. Lo que sí lo caza es el test que recorre los nombres usados.
     */
    public static function path(string $name): string
    {
        return self::PATHS[$name] ?? '';
    }

    /** ¿Existe? Lo usa el test que comprueba que nadie pide uno que no está. */
    public static function has(string $name): bool
    {
        return isset(self::PATHS[$name]);
    }

    /** @return list<string> */
    public static function names(): array
    {
        return array_keys(self::PATHS);
    }
